        ) DATA                   
  WHERE RNUM BETWEEN ((#{page}-1) * #{rows} + 1) and (#{page} * #{rows} )

mapper.select:
SELECT SBH.BOM_CHANGE_DATE, SBH.BOM_CTGRY, SBH.BOM_SE, SBH.ALTRTV_BOM, SBH.REQREQY_CALC_MTH, SBH.EFECT_BGNDE, SBH.EFECT_ENDDE, SBH.DIVISION_CODE, SBH.ITEM_TYPE, SBH.ITEM_CODE, SBH.BASS_UNIT, SBH.STDR_QY, SBH.BOM_STATUS, SBI.BOM_RWMATR, SBI.BOM, SBI.BOM_PRDLST_NODE, SBI.INNER_CNT, SBI.PRDCTN_VER, SBI.ITEM_GROUP, SBI.BOM_PRDLST, SBI.PO_SNR, SBI.OBJECT_ITEM, SBI.CMMRC_CODE_NO, SBI.QY, SBI.BOM_LEVEL, SBI.COURS, SBI.TABLE_INDX, SBI.BOM_COURS, SBI.BOM_CTGRY_NEXT, SBI.BOM_NO_NEXT, SBI.BOM_USE_NEXT, SBI.BOM_ALTRTV_NEXT, SBI.ALTRTV_PRDLST_GROUP, SBI.DRCTR_ALTRTV_PRDLST, SBI.BYPRD_OCCRRNC_AT, SBI.BOM_USE_AT, SBI.LAST_ITEM_AT, SBI.SPECL_ITEM_TYPE, SBI.ALTRTV_ITEM, SBI.SA_SE, SBI.BK_ITEM, SBI.ALTRTV_RAWMTRL_AT FROM STD_BOM_HIST_HDER SBH INNER JOIN STD_BOM_HIST_ITEM SBI ON SBH.BOM_CHANGE_DATE = SBI.BOM_CHANGE_DATE AND SBH.BOM_CTGRY = SBI.BOM_CTGRY AND SBH.BOM_SE = SBI.BOM_SE AND SBH.ALTRTV_BOM = SBI.ALTRTV_BOM AND SBH.REQREQY_CALC_MTH = SBI.REQREQY_CALC_MTH WHERE 1 = 1
AND REPLACE(#{PRIC_RQEST_DATE}, '-', '') BETWEEN SBH.EFECT_BGNDE AND SBH.EFECT_ENDDE
AND SBH.ITEM_CODE = #{ITEM_CODE}

SELECT DISTINCT A.PRESENTN_NO ,B.XPORT_STTEMNT_CNT ,A.HS_CODE ,B.THNG_SE ,ISSUE_STTEMNT_PC_KRW AS STTEMNT_PC_KRW ,ISSUE_ACCMLT_ORDER_QY AS ACCMLT_ORDER_QY ,A.KRW_CRNCY ,A.BASS_UNIT ,TRUNC(RAWMTRL.DRWBAK_AMOUNT) AS DRWBAK_AMOUNT ,A.LF_PRICE_TRGT ,A.TAX_RATE_TRGT ,TO_CHAR(A.CREATE_DATE, 'RRRR-MM-DD') AS CREATE_DATE ,A.EXECUT_AT ,A.DIVISION_CODE ,C.UNIPASS_ID ,C.UNIPASS_DOC_BOX_CODE ,A.STTEMNT_DOC_STLE ,A.EXECUT_STATUS ,A.SUBMIT_NO ,A.REGIST_RCEPT_NO FROM DRWBAK_REQSTDOC_CMMN A INNER JOIN (SELECT COMPANY_CODE, DIVISION_CODE, PRESENTN_NO, THNG_SE, COUNT(1) AS XPORT_STTEMNT_CNT, SUM(ACCMLT_ORDER_QY) AS ISSUE_ACCMLT_ORDER_QY, SUM(STTEMNT_PC_KRW) AS ISSUE_STTEMNT_PC_KRW FROM (SELECT DISTINCT COMPANY_CODE, DIVISION_CODE, PRESENTN_NO, XPORT_STTEMNT_NO, LNE_NO, POUCH_NO, ACCMLT_ORDER_QY, BASS_UNIT, STTEMNT_PC_KRW, THNG_SEQ, THNG_SE FROM (SELECT T.COMPANY_CODE, T.DIVISION_CODE, T.PRESENTN_NO, T.XPORT_STTEMNT_NO, T.LNE_NO, T.POUCH_NO, T.ACCMLT_ORDER_QY, T.BASS_UNIT, T.THNG_SE, TRUNC(T.STTEMNT_PC_KRW) AS STTEMNT_PC_KRW, T.THNG_SEQ, CASE WHEN B.IMP_BASS_UNIT = A.BASS_UNIT THEN A.USGQTY ELSE (CASE WHEN B.IMP_BASS_UNIT = 'KG' THEN A.USGQTY / 1000 WHEN B.IMP_BASS_UNIT = 'LB' THEN A.USGQTY / 0.453592 / 1000 WHEN B.IMP_BASS_UNIT = 'DR' THEN A.USGQTY / 1000 / 30 WHEN B.IMP_BASS_UNIT = 'GR' THEN A.USGQTY / 0.064799 WHEN B.IMP_BASS_UNIT = 'MT' THEN A.USGQTY / 1000 / 1000 ELSE B.QY END) END AS USGQTY FROM DRWBAK_REQSTDOC_TRGET_THNG T INNER JOIN DRWBAK_REQSTDOC_CMMN TT ON T.COMPANY_CODE = TT.COMPANY_CODE AND T.DIVISION_CODE = TT.DIVISION_CODE AND T.PRESENTN_NO = TT.PRESENTN_NO INNER JOIN DRWBAK_REQSTDOC_INCME_RAWMTRL A ON T.COMPANY_CODE = A.COMPANY_CODE AND T.PRESENTN_NO = A.PRESENTN_NO AND T.THNG_SEQ = A.THNG_SEQ INNER JOIN INCME_LOCAL_BNT_SM B ON A.COMPANY_CODE = B.COMPANY_CODE AND A.RAWMTRL_CODE = B.ITEM_CODE AND A.LNE_NO = B.LNE_NO AND A.POUCH_NO = B.POUCH_NO AND A.IMPDEC_NO = B.IMPDEC_NO WHERE TRUNC(A.CSTMS, 4) > 0 AND T.COMPANY_CODE = #{COMPANY_CODE} AND T.DIVISION_CODE = #{DIVISION_CODE} AND T.DSPTH_DATE BETWEEN #{DSPTH_DATE_FROM} AND #{DSPTH_DATE_TO}
AND T.ITEM_CODE = #{SEARCH_KEY_WORD}
AND T.ITEM_CODE LIKE #{SEARCH_KEY_WORD}|| '%'
AND T.ITEM_CODE LIKE '%'||#{SEARCH_KEY_WORD}|| '%'
AND T.ITEM_NM = #{SEARCH_KEY_WORD}
AND T.ITEM_NM LIKE #{SEARCH_KEY_WORD}|| '%'
AND T.ITEM_NM LIKE '%'||#{SEARCH_KEY_WORD}|| '%'
AND T.THNG_SE = #{THNG_SE}
) X WHERE TRUNC(USGQTY, 3) > 0.000999999999999) GROUP BY COMPANY_CODE, DIVISION_CODE, PRESENTN_NO, THNG_SE, BASS_UNIT) B ON A.COMPANY_CODE = B.COMPANY_CODE AND A.DIVISION_CODE = B.DIVISION_CODE AND A.PRESENTN_NO = B.PRESENTN_NO INNER JOIN (SELECT COMPANY_CODE ,PRESENTN_NO ,TRUNC(SUM(TAX_SUM), -1) AS DRWBAK_AMOUNT FROM (SELECT AA.COMPANY_CODE ,AA.PRESENTN_NO ,(CASE WHEN BB.IMP_BASS_UNIT = AA.BASS_UNIT THEN AA.USGQTY ELSE (CASE WHEN BB.IMP_BASS_UNIT = 'KG' THEN AA.USGQTY / 1000 WHEN BB.IMP_BASS_UNIT = 'LB' THEN AA.USGQTY / 0.453592 / 1000 WHEN BB.IMP_BASS_UNIT = 'DR' THEN AA.USGQTY / 1000 / 30 WHEN BB.IMP_BASS_UNIT = 'GR' THEN AA.USGQTY / 0.064799 WHEN BB.IMP_BASS_UNIT = 'MT' THEN AA.USGQTY / 1000 / 1000 ELSE BB.QY END) END) AS USGQTY ,TRUNC(AA.CSTMS) + TRUNC(AA.INTTAX) + TRUNC(AA.ECX_AMOUNT) + TRUNC(AA.AGSPT) + TRUNC(AA.TRANTAX) + TRUNC(AA.LQTX_AMOUNT) AS TAX_SUM ,Z.DRWBAK_LMTT_REGLTN FROM DRWBAK_REQSTDOC_INCME_RAWMTRL AA INNER JOIN DRWBAK_REQSTDOC_TRGET_THNG TT ON AA.COMPANY_CODE = TT.COMPANY_CODE AND AA.PRESENTN_NO = TT.PRESENTN_NO AND AA.THNG_SEQ = TT.THNG_SEQ INNER JOIN DRWBAK_REQSTDOC_CMMN RC ON RC.COMPANY_CODE = AA.COMPANY_CODE AND RC.PRESENTN_NO = AA.PRESENTN_NO INNER JOIN INCME_LOCAL_BNT_SM BB ON AA.COMPANY_CODE = BB.COMPANY_CODE AND AA.RAWMTRL_CODE = BB.ITEM_CODE AND AA.LNE_NO = BB.LNE_NO AND AA.POUCH_NO = BB.POUCH_NO AND AA.IMPDEC_NO = BB.IMPDEC_NO LEFT OUTER JOIN DRWBAK_LMTT_REGLTN Z ON BB.HS_CODE = Z.HS_CODE AND BB.ACPT_DATE BETWEEN Z.EFECT_BGNDE AND Z.EFECT_ENDDE WHERE TRUNC(AA.CSTMS, 4) > 0 AND AA.COMPANY_CODE = #{COMPANY_CODE} ) WHERE TRUNC(USGQTY, 3) > 0.000999999999999 GROUP BY COMPANY_CODE, PRESENTN_NO) RAWMTRL ON A.COMPANY_CODE = RAWMTRL.COMPANY_CODE AND A.PRESENTN_NO = RAWMTRL.PRESENTN_NO INNER JOIN COMPANY C ON A.COMPANY_CODE = C.COMPANY_CODE WHERE A.COMPANY_CODE = #{COMPANY_CODE} AND TRUNC(RAWMTRL.DRWBAK_AMOUNT, -1) > 9999 -- 10,000 이상건만 신청
AND A.HS_CODE = #{HS_CODE}
AND A.REGIST_RCEPT_NO = #{REGIST_RCEPT_NO}
AND A.PRESENTN_NO = #{PRESENTN_NO}
AND A.LF_PRICE_TRGT = #{LF_PRICE_TRGT_YN}
AND A.EXECUT_STATUS = #{EXECUT_STATUS}

SELECT A.PRESENTN_NO ,A.REGIST_RCEPT_NO --,FC01_GET_MAKER_NM(A.COMPANY_CODE, A.DIVISION_CODE, A.PRESENTN_NO, B.XPORT_STTEMNT_NO) AS MANUFAC_NAME ,A.MANUFAC_NAME ,COMP.COMPANY_NM ,NVL(TO_CHAR(A.DRWBAK_COMP_DATE,'YYYYMMDD'), '') AS DRWBAK_COMP_DATE ,A.BANK_CODE ,BM.BANK_NM ,A.ACNUTNO ,A.DRWBAK_SE ,'['||A.REQREQY_CALC_MTH||'] ' || FC01_GET_CODE_NM('BOMC', A.REQREQY_CALC_MTH) AS REQREQY_CALC_MTH ,TRUNC(RAWMTRL.CSTMS, 0) AS CSTMS ,TRUNC(RAWMTRL.INTTAX, 0) AS INTTAX ,TRUNC(RAWMTRL.ECX_AMOUNT, 0) AS ECX_AMOUNT ,TRUNC(RAWMTRL.AGSPT, 0) AS AGSPT ,TRUNC(RAWMTRL.TRANTAX, 0) AS TRANTAX ,TRUNC(RAWMTRL.LQTX_AMOUNT, 0) AS LQTX_AMOUNT ,TRUNC(RAWMTRL.DRWBAK_AMOUNT, 0) AS DRWBAK_AMOUNT FROM DRWBAK_REQSTDOC_CMMN A INNER JOIN COMPANY COMP ON A.COMPANY_CODE = COMP.COMPANY_CODE INNER JOIN (SELECT COMPANY_CODE ,PRESENTN_NO ,TRUNC(SUM(A.CSTMS), 0) AS CSTMS ,TRUNC(SUM(A.INTTAX), 0) AS INTTAX ,TRUNC(SUM(A.ECX_AMOUNT), 0) AS ECX_AMOUNT ,TRUNC(SUM(A.AGSPT), 0) AS AGSPT ,TRUNC(SUM(A.TRANTAX), 0) AS TRANTAX ,TRUNC(SUM(A.LQTX_AMOUNT), 0) AS LQTX_AMOUNT ,TRUNC(SUM(A.DRWBAK_AMOUNT), 0) AS DRWBAK_AMOUNT FROM (SELECT AA.COMPANY_CODE ,AA.PRESENTN_NO ,(CASE WHEN BB.IMP_BASS_UNIT = AA.BASS_UNIT THEN AA.USGQTY ELSE (CASE WHEN BB.IMP_BASS_UNIT = 'KG' THEN AA.USGQTY / 1000 WHEN BB.IMP_BASS_UNIT = 'LB' THEN AA.USGQTY / 0.453592 / 1000 WHEN BB.IMP_BASS_UNIT = 'DR' THEN AA.USGQTY / 1000 / 30 WHEN BB.IMP_BASS_UNIT = 'GR' THEN AA.USGQTY / 0.064799 WHEN BB.IMP_BASS_UNIT = 'MT' THEN AA.USGQTY / 1000 / 1000 ELSE BB.QY END) END) AS USGQTY, AA.CSTMS, AA.INTTAX, AA.ECX_AMOUNT, AA.AGSPT, AA.TRANTAX, AA.LQTX_AMOUNT, AA.DRWBAK_AMOUNT FROM DRWBAK_REQSTDOC_INCME_RAWMTRL AA INNER JOIN DRWBAK_REQSTDOC_TRGET_THNG TT ON AA.COMPANY_CODE = TT.COMPANY_CODE AND AA.PRESENTN_NO = TT.PRESENTN_NO AND AA.THNG_SEQ = TT.THNG_SEQ INNER JOIN DRWBAK_REQSTDOC_CMMN RC ON RC.COMPANY_CODE = AA.COMPANY_CODE AND RC.PRESENTN_NO = AA.PRESENTN_NO INNER JOIN INCME_LOCAL_BNT_SM BB ON AA.COMPANY_CODE = BB.COMPANY_CODE AND AA.RAWMTRL_CODE = BB.ITEM_CODE AND AA.LNE_NO = BB.LNE_NO AND AA.POUCH_NO = BB.POUCH_NO AND AA.IMPDEC_NO = BB.IMPDEC_NO WHERE TRUNC(AA.CSTMS, 4) > 0 AND AA.COMPANY_CODE = #{COMPANY_CODE} AND AA.PRESENTN_NO = #{P_PRESENTN_NO} AND RC.DIVISION_CODE = #{DIVISION_CODE} ) A WHERE TRUNC(USGQTY, 3) > 0.000999999999999 GROUP BY COMPANY_CODE, PRESENTN_NO) RAWMTRL ON A.COMPANY_CODE = RAWMTRL.COMPANY_CODE AND A.PRESENTN_NO = RAWMTRL.PRESENTN_NO INNER JOIN BANK_MST BM ON BM.COMPANY_CODE = A.COMPANY_CODE AND BM.DIVISION_CODE = A.DIVISION_CODE AND BM.BANK_CODE = A.BANK_CODE INNER JOIN DRWBAK_REQSTDOC_TRGET_THNG B ON A.PRESENTN_NO = B.PRESENTN_NO AND A.COMPANY_CODE = B.COMPANY_CODE WHERE A.COMPANY_CODE = #{COMPANY_CODE}
AND A.DIVISION_CODE = #{DIVISION_CODE}
AND A.PRESENTN_NO = #{P_PRESENTN_NO} AND ROWNUM = 1

SELECT EXPDECL_MANAGE_NO, XPORT_STTEMNT_NO, DSPTH_DATE, HS_CODE, MAX(MANUFAC_NAME) AS MANUFAC_NAME, SUM(STTEMNT_PC_FGCRY) AS STTEMNT_PC_FGCRY, MAX(CRNCY) AS CRNCY, XPORT_SE, SUM(ITEM_QTY) AS SUM_ITEM_QTY, MAX(SLE_UNIT) AS SLE_UNIT, SUM(STTEMNT_PC_KRW) AS SUM_STTEMNT_PC_KRW, MAX(INV_NO) AS INV_NO, COMPANY_CODE, DIVISION_CODE, CONFIRM_YN, CONFIRM_DATE, MIN(CREATE_DATE) AS CREATE_DATE, MAX(UPDATE_DATE) AS UPDATE_DATE, PRESENTN_NO FROM (SELECT A.EXPDECL_MANAGE_NO, A.XPORT_STTEMNT_NO, A.DSPTH_DATE, A.HS_CODE, A.MANUFAC_NAME, A.STTEMNT_PC_FGCRY, A.CRNCY, A.XPORT_SE, NVL('['||A.XPORT_SE||'] '|| CD.CODE_NM, A.XPORT_SE) AS XPORT_SE_NAME, A.ITEM_QTY, A.SLE_UNIT, A.STTEMNT_PC_KRW, A.INV_NO, A.COMPANY_CODE, A.DIVISION_CODE, (CASE WHEN B.PRESENTN_NO IS NULL THEN 'N' ELSE 'Y' END) AS CONFIRM_YN, (CASE WHEN B.PRESENTN_NO IS NULL THEN NULL ELSE TO_CHAR(B.CREATE_DATE, 'RRRRMMDD') END) AS CONFIRM_DATE, B.PRESENTN_NO, AA.REGIST_RCEPT_NO, TO_CHAR(ECR.CREATE_DATE, 'RRRRMMDD') AS CREATE_DATE, TO_CHAR(ECR.UPDATE_DATE, 'RRRRMMDD') AS UPDATE_DATE
FROM EXPORT_CERT_MST A LEFT OUTER JOIN DRWBAK_REQSTDOC_TRGET_THNG B ON A.COMPANY_CODE = B.COMPANY_CODE AND A.DIVISION_CODE = B.DIVISION_CODE AND A.XPORT_STTEMNT_NO = B.XPORT_STTEMNT_NO AND A.LNE_NO = B.LNE_NO AND A.POUCH_NO = B.POUCH_NO AND A.ITEM_CODE = B.ITEM_CODE LEFT OUTER JOIN DRWBAK_REQSTDOC_CMMN AA ON A.COMPANY_CODE = AA.COMPANY_CODE AND A.DIVISION_CODE = AA.DIVISION_CODE AND B.PRESENTN_NO = AA.PRESENTN_NO LEFT OUTER JOIN EXPORT_CONFIRM_REASON ECR ON ECR.COMPANY_CODE = A.COMPANY_CODE AND ECR.DIVISION_CODE = A.DIVISION_CODE AND ECR.EXPDECL_MANAGE_NO = A.EXPDECL_MANAGE_NO AND ECR.XPORT_STTEMNT_NO = A.XPORT_STTEMNT_NO AND ECR.LNE_NO = A.LNE_NO AND ECR.POUCH_NO = A.POUCH_NO AND ECR.ITEM_CODE = A.ITEM_CODE LEFT OUTER JOIN COM_CD CD ON A.XPORT_SE = CD.CODE_CD AND CD.CATEGORY_CD = 'ETC' -- 수출거래구분 WHERE A.DSPTH_DATE BETWEEN REPLACE(#{CAL_F_SEARCH_DATE}, '-', '') || '01' AND TO_CHAR(LAST_DAY(TO_DATE(#{CAL_T_SEARCH_DATE}, 'RRRR-MM'))) AND A.HS_CODE IS NOT NULL AND A.COMPANY_CODE = #{COMPANY_CODE}
AND A.DIVISION_CODE = #{DIVISION_CODE}
AND A.HS_CODE LIKE #{HS_CODE} || '%'
AND A.XPORT_SE = #{XPORT_SE}
AND A.ITEM_CODE LIKE #{ITEM_CODE} || '%'
AND A.XPORT_STTEMNT_NO LIKE #{XPORT_STTEMNT_NO} || '%'
AND UPPER(A.MANUFAC_NAME) LIKE UPPER( '%' || #{MANUFAC_NAME} || '%' )
AND A.ITEM_CODE = #{SEARCH_KEY_WORD}
AND A.ITEM_CODE LIKE #{SEARCH_KEY_WORD}|| '%'
AND A.ITEM_CODE LIKE '%'||#{SEARCH_KEY_WORD}|| '%'
AND A.ITEM_NM = #{SEARCH_KEY_WORD}
AND A.ITEM_NM LIKE #{SEARCH_KEY_WORD}|| '%'
AND A.ITEM_NM LIKE '%'||#{SEARCH_KEY_WORD}|| '%'
AND A.INV_NO = #{SEARCH_KEY_WORD}
AND A.INV_NO LIKE #{SEARCH_KEY_WORD}|| '%'
AND A.INV_NO LIKE '%'||#{SEARCH_KEY_WORD}|| '%'
) LST WHERE REGIST_RCEPT_NO IS NULL
AND LST.CONFIRM_YN = #{CONFIRM_YN}
GROUP BY EXPDECL_MANAGE_NO, XPORT_STTEMNT_NO, DSPTH_DATE, HS_CODE, XPORT_SE, COMPANY_CODE, DIVISION_CODE, CONFIRM_YN, CONFIRM_DATE, PRESENTN_NO ORDER BY DSPTH_DATE ASC

SELECT EXPDECL_MANAGE_NO, XPORT_STTEMNT_NO, MAX(MANUFAC_NAME) AS MANUFAC_NAME, COMPANY_NM, DSPTH_DATE, NATION_CODE, SUM(ITEM_QTY) AS ITEM_QTY, SUM(DECODE(PRESENTN_NO,NULL,0,ITEM_QTY)) AS CONFIRM_ITEM_QTY, SUM(DECODE(PRESENTN_NO,NULL,ITEM_QTY,0)) AS PENDING_ITEM_QTY, MAX(INV_NO) AS INV_NO
FROM (SELECT A.EXPDECL_MANAGE_NO, A.XPORT_STTEMNT_NO, A.MANUFAC_NAME, C.COMPANY_NM, A.DSPTH_DATE, A.NATION_CODE, A.ITEM_QTY, A.INV_NO, B.PRESENTN_NO FROM EXPORT_CERT_MST A INNER JOIN COMPANY C ON A.COMPANY_CODE = C.COMPANY_CODE LEFT OUTER JOIN DRWBAK_REQSTDOC_TRGET_THNG B ON A.COMPANY_CODE = B.COMPANY_CODE AND A.DIVISION_CODE = B.DIVISION_CODE AND A.XPORT_STTEMNT_NO = B.XPORT_STTEMNT_NO AND A.LNE_NO = B.LNE_NO AND A.POUCH_NO = B.POUCH_NO AND A.ITEM_CODE = B.ITEM_CODE LEFT OUTER JOIN DRWBAK_REQSTDOC_CMMN AA ON A.COMPANY_CODE = AA.COMPANY_CODE AND A.DIVISION_CODE = AA.DIVISION_CODE AND B.PRESENTN_NO = AA.PRESENTN_NO
WHERE A.HS_CODE IS NOT NULL AND A.EXPDECL_MANAGE_NO = #{P_EXPDECL_MANAGE_NO} AND A.COMPANY_CODE = #{COMPANY_CODE} AND A.DIVISION_CODE = #{P_DIVISION_CODE} AND A.XPORT_STTEMNT_NO = #{P_XPORT_STTEMNT_NO}
) LST
GROUP BY EXPDECL_MANAGE_NO, XPORT_STTEMNT_NO, COMPANY_NM, DSPTH_DATE, NATION_CODE

SELECT DISTINCT A.PRESENTN_NO FROM DRWBAK_REQSTDOC_CMMN A
 WHERE A.COMPANY_CODE = #{COMPANY_CODE}
   AND A.DIVISION_CODE = #{DIVISION_CODE}
   AND A.MANUFAC_NAME = #{MANUFAC_NAME}
   AND A.XPORT_TYPE = #{XPORT_TYPE}
   AND A.HS_CODE = #{HS_CODE}
   AND A.DRWBAK_MONTH = #{DRWBAK_MONTH}
   AND A.SUBMIT_NO IS NULL
   AND A.REGIST_RCEPT_NO IS NULL

mapper.insert:
SELECT #{COMPANY_CODE}|| #{DIVISION_CODE}||'-'||TO_CHAR(SYSDATE, 'RRRRMMDD') ||'-'|| LPAD(CASE WHEN COUNT(1) = 0 THEN '1' ELSE TO_CHAR(COUNT(1)+1) END, 4, '0') FROM DRWBAK_REQSTDOC_CMMN A WHERE A.PRESENTN_NO LIKE #{COMPANY_CODE}|| #{DIVISION_CODE}||'-'||TO_CHAR(SYSDATE, 'RRRRMMDD') || '%'
INSERT INTO DRWBAK_REQSTDOC_CMMN (COMPANY_CODE, PRESENTN_NO, STTEMNT_DOC_STLE, DRWBAK_SE_CODE, DRWBAK_SE, XPORT_TYPE, CSMHSE_CODE, CSMHSE_TEXT, ACNUTNO, BANK_CODE, ECTMRK, BIZRNO, TELNO_1, CSTBRKR, HS_CODE, NATION_CODE, REQREQY_CALC_MTH, BOM_TYPE, ITEM_NM, STTEMNT_PC_KRW, KRW_CRNCY, ACCMLT_ORDER_QY, BASS_UNIT, CSTMS, INTTAX, ECX_AMOUNT, AGSPT, DRWBAK_AMOUNT, ACPLC_CRNCY, DIVISION_CODE, MANUFAC_NAME, DRWBAK_MONTH) SELECT DISTINCT A.COMPANY_CODE ,#{KEY_PRESENTN_NO} AS PRESENTN_NO ,'GOVCBR5DA' AS STTEMNT_DOC_STLE -- 고정값(환급신청) ,'3' AS DRWBAK_SE_CODE ,'개별' AS DRWBAK_SE ,A.XPORT_TYPE AS DRWBAK_DELNG_SE -- 수출형태가 환급거래구분으로 쓰임 ,C.CSMHSE_CODE -- 세관코드 ,FC01_GET_CODE_NM('CUSC', C.CSMHSE_CODE) AS CSMHSE_TEXT ,C.ACNUTNO ,C.BANK_CODE ,C.ECTMRK ,C.BIZRNO ,C.TELNO_1 ,C.CSTBRKR ,A.HS_CODE ,MAX(A.NATION_CODE) AS NATION_CODE ,'02' AS REQREQY_CALC_MTH -- 소요량구분:단위설계소요량 ,FC01_GET_CODE_NM('BOMC', '02') AS BOM_TYPE -- -- 소요량구분:단위설계소요량 ,MAX(A.ITEM_NM) AS ITEM_NM ,0 AS STTEMNT_PC_KRW -- 신고가격-원화 ,'KRW' AS KRW_CRNCY ,0 AS ACCMLT_ORDER_QY -- 수출 수량 SUM ,MAX(A.SLE_UNIT) AS BASS_UNIT ,0 AS CSTMS -- 병지 관세 SUM ,0 AS INTTAX -- 내국세 ,0 AS ECX_AMOUNT -- 교육세 ,0 AS AGSPT --농특세 ,0 AS DRWBAK_AMOUNT --환급금액 ,'' AS ACPLC_CRNCY --통화 키 ,A.DIVISION_CODE --플렌트 코드 ,A.MANUFAC_NAME ,SUBSTR(A.DSPTH_DATE, 1, 6) FROM EXPORT_CERT_MST A INNER JOIN COMPANY C ON A.COMPANY_CODE = C.COMPANY_CODE WHERE A.COMPANY_CODE = #{COMPANY_CODE} AND A.DIVISION_CODE = #{DIVISION_CODE} AND A.MANUFAC_NAME = #{MANUFAC_NAME} AND A.XPORT_TYPE = #{XPORT_TYPE} AND A.HS_CODE = #{HS_CODE} AND SUBSTR(A.DSPTH_DATE, 1, 6) = #{DRWBAK_MONTH}
AND EXISTS (SELECT 1 FROM DRWBAK_CONFIRM_TEMP X WHERE X.XPORT_STTEMNT_NO = A.XPORT_STTEMNT_NO AND X.HS_CODE = A.HS_CODE AND X.MANUFAC_NAME = A.MANUFAC_NAME AND X.XPORT_SE = A.XPORT_SE AND X.MY_KEY = #{MY_KEY}) GROUP BY A.COMPANY_CODE, A.MANUFAC_NAME, A.XPORT_TYPE, C.CSMHSE_CODE, C.ACNUTNO, C.BANK_CODE, C.ECTMRK, C.BIZRNO, C.TELNO_1, C.CSTBRKR, A.HS_CODE, A.DIVISION_CODE, SUBSTR(A.DSPTH_DATE, 1, 6)

SELECT NVL(MAX(A.THNG_SEQ), 0) AS PRE_THNG_SEQ_NUMBER FROM DRWBAK_REQSTDOC_TRGET_TEMP A WHERE A.PRESENTN_NO = #{KEY_PRESENTN_NO} AND A.COMPANY_CODE = #{COMPANY_CODE} AND A.DIVISION_CODE = #{DIVISION_CODE}
INSERT INTO DRWBAK_REQSTDOC_TRGET_TEMP (COMPANY_CODE,PRESENTN_NO,THNG_SEQ,ITEM_CODE,ITEM_NM,THNG_SE,XPORT_STTEMNT_NO,LNE_NO,POUCH_NO,DSPTH_DATE,ACCMLT_ORDER_QY,BASS_UNIT,STTEMNT_PC_KRW,KRW_CRNCY,DIVISION_CODE) SELECT COMPANY_CODE, PRESENTN_NO, THNG_SEQ, ITEM_CODE, ITEM_NM, XPORT_SE, XPORT_STTEMNT_NO, LNE_NO, POUCH_NO, DSPTH_DATE, ABLE_ITEM_QTY, -- ITEM_QTY SLE_UNIT, STTEMNT_PC_KRW, KRW_CRNCY, DIVISION_CODE FROM (SELECT A.COMPANY_CODE, #{KEY_PRESENTN_NO} AS PRESENTN_NO, (ROW_NUMBER() OVER(ORDER BY A.XPORT_STTEMNT_NO, A.DSPTH_DATE ASC)) + ${PRE_THNG_SEQ_NUMBER} AS THNG_SEQ, A.ITEM_CODE, A.ITEM_NM, A.XPORT_SE, A.XPORT_STTEMNT_NO, A.LNE_NO, A.POUCH_NO, A.DSPTH_DATE, A.ABLE_ITEM_QTY, -- A.ITEM_QTY A.SLE_UNIT, A.STTEMNT_PC_KRW, 'KRW' AS KRW_CRNCY, A.DIVISION_CODE, B.PRESENTN_NO AS PRE_PRESENTN_NO FROM EXPORT_CERT_MST A LEFT OUTER JOIN DRWBAK_REQSTDOC_TRGET_THNG B ON A.COMPANY_CODE = B.COMPANY_CODE AND A.DIVISION_CODE = B.DIVISION_CODE AND A.XPORT_STTEMNT_NO = B.XPORT_STTEMNT_NO AND A.LNE_NO = B.LNE_NO AND A.POUCH_NO = B.POUCH_NO WHERE A.COMPANY_CODE = #{COMPANY_CODE} AND A.DIVISION_CODE = #{DIVISION_CODE} AND A.MANUFAC_NAME = #{MANUFAC_NAME} AND A.XPORT_TYPE = #{XPORT_TYPE} AND A.HS_CODE = #{HS_CODE} AND SUBSTR(A.DSPTH_DATE, 1, 6) = #{DRWBAK_MONTH}
AND EXISTS (SELECT 1 FROM DRWBAK_CONFIRM_TEMP X WHERE X.XPORT_STTEMNT_NO = A.XPORT_STTEMNT_NO AND X.HS_CODE = A.HS_CODE AND X.MANUFAC_NAME = A.MANUFAC_NAME AND X.XPORT_SE = A.XPORT_SE AND X.MY_KEY = #{MY_KEY}) ) WHERE PRE_PRESENTN_NO IS NULL

mapper.select:
SELECT * 
  FROM DRWBAK_REQSTDOC_TRGET_TEMP A 
 WHERE A.COMPANY_CODE = #{COMPANY_CODE}
