DELETE FROM CTRM_CMMN A 
 WHERE A.PRESENTN_NO = #{KEY_PRESENTN_NO}
   AND A.COMPANY_CODE = #{COMPANY_CODE}
   AND A.DIVISION_CODE = #{DIVISION_CODE}

mapper.select:
SELECT A.PRESENTN_NO ,CASE WHEN ISSUE_TYPE = '02' THEN '기납증' WHEN ISSUE_TYPE = '04' THEN '분증' ELSE '알수없는코드' END AS ISSUE_TYPE_NAME ,A.CSTMR_NM_1 ,A.RPRSNTV_NM_1 ,A.HS_CODE ,MAX(B.ITEM_CODE) AS ITEM_CODE ,MAX(B.ITEM_NM) AS ITEM_NM ,COUNT(1) AS DOC_ITEM_CNT ,TRUNC(AMT.STTEMNT_PC_KRW,0) AS STTEMNT_PC_KRW ,TRUNC(A.STTEMNT_PC_KRW,0) AS STTEMNT_PC_KRW ,A.BASS_UNIT ,TRUNC(AMT.DRWBAK_AMOUNT, -1) AS DRWBAK_AMOUNT ,TRUNC(A.DRWBAK_AMOUNT, -1) AS DRWBAK_AMOUNT ,A.EXECUT_AT ,CASE WHEN A.EXECUT_AT != 'Y' THEN '미접수' ELSE '접수' END AS EXECUT_AT_NAME ,A.COMPANY_CODE ,A.DIVISION_CODE ,A.BASE_SOURCE_YYYYMM ,A.CUSTOMER_CODE ,A.SUBMIT_NO ,A.EXECUT_STATUS ,A.ISSUE_TYPE ,A.REGIST_RCEPT_NO FROM CTRM_CMMN A INNER JOIN (SELECT COMPANY_CODE ,DIVISION_CODE ,PRESENTN_NO ,SEQ ,ITEM_CODE ,ITEM_NM ,ACCMLT_ORDER_QY ,BASS_UNIT ,STTEMNT_PC_KRW ,KRW_CRNCY ,CSTMS ,INTTAX ,ECX_AMOUNT ,AGSPT ,DRWBAK_AMOUNT ,ACPLC_CRNCY ,BASIS_DOC_NO ,SUPT_DOC_SE ,CSTMR_ITEM ,SUPT_DOC_ITEM_SEQ ,CHIT_FRMTRM_DATE FROM CTRM_TRGET_THNG UNION ALL SELECT COMPANY_CODE ,DIVISION_CODE ,PRESENTN_NO ,SEQ ,RAWMTRL_CODE ,ITEM_NM ,USGQTY ,BASS_UNIT ,STTEMNT_PC_KRW ,'KRW' ,CSTMS ,INTTAX ,ECX_AMOUNT ,AGSPT ,DRWBAK_AMOUNT ,ACPLC_CRNCY ,BASIS_DOC_NO ,SUPT_DOC_SE ,CSTMR_ITEM ,SUPT_DOC_ITEM_SEQ ,CHIT_FRMTRM_DATE FROM CTRM_THING_RAWMTRL) B ON A.COMPANY_CODE = B.COMPANY_CODE AND A.DIVISION_CODE = B.DIVISION_CODE AND A.PRESENTN_NO = B.PRESENTN_NO
LEFT OUTER JOIN (SELECT PRESENTN_NO ,COMPANY_CODE ,DIVISION_CODE ,SUM(ACCMLT_ORDER_QY) AS ACCMLT_ORDER_QY ,SUM(STTEMNT_PC_KRW) AS STTEMNT_PC_KRW ,SUM(TAX_SUM) AS DRWBAK_AMOUNT FROM (SELECT PRESENTN_NO , COMPANY_CODE , DIVISION_CODE , ACCMLT_ORDER_QY , STTEMNT_PC_KRW , SUM(TAX_SUM) AS TAX_SUM FROM (SELECT A.PRESENTN_NO , A.COMPANY_CODE , A.DIVISION_CODE , A.ACCMLT_ORDER_QY , A.STTEMNT_PC_KRW , (TRUNC(AA.CSTMS, -1)+TRUNC(AA.INTTAX, -1)+TRUNC(AA.ECX_AMOUNT, -1)+TRUNC(AA.AGSPT, -1)+TRUNC(AA.TRANTAX, -1)+TRUNC(AA.LQTX_AMOUNT, -1)) AS TAX_SUM , CASE WHEN B.IMP_BASS_UNIT = AA.BASS_UNIT THEN AA.USGQTY ELSE (CASE WHEN B.IMP_BASS_UNIT = 'KG' THEN AA.USGQTY / 1000 WHEN B.IMP_BASS_UNIT = 'LB' THEN AA.USGQTY / 0.453592 / 1000 WHEN B.IMP_BASS_UNIT = 'DR' THEN AA.USGQTY / 1000 / 30 WHEN B.IMP_BASS_UNIT = 'GR' THEN AA.USGQTY / 0.064799 WHEN B.IMP_BASS_UNIT = 'MT' THEN AA.USGQTY / 1000 / 1000 ELSE B.QY END) END AS USGQTY FROM CTRM_TRGET_THNG A INNER JOIN CTRM_INCME_RAWMTRL AA ON A.COMPANY_CODE = AA.COMPANY_CODE AND A.DIVISION_CODE = AA.DIVISION_CODE AND A.PRESENTN_NO = AA.PRESENTN_NO AND A.SEQ = AA.SEQ INNER JOIN INCME_LOCAL_BNT_SM B ON AA.COMPANY_CODE = B.COMPANY_CODE AND AA.IMPDEC_NO = B.IMPDEC_NO AND AA.LNE_NO = B.LNE_NO AND AA.POUCH_NO = B.POUCH_NO AND AA.RAWMTRL_CODE = B.ITEM_CODE WHERE A.COMPANY_CODE = #{COMPANY_CODE} AND A.DIVISION_CODE = #{DIVISION_CODE} --AND A.PRESENTN_NO = 'I-1500-1200-20241212-0957' ) WHERE TRUNC(USGQTY, 3) > 0.000999999999999 GROUP BY PRESENTN_NO, COMPANY_CODE, DIVISION_CODE, ACCMLT_ORDER_QY, STTEMNT_PC_KRW ) GROUP BY PRESENTN_NO, COMPANY_CODE, DIVISION_CODE) AMT ON B.COMPANY_CODE = AMT.COMPANY_CODE AND B.DIVISION_CODE = AMT.DIVISION_CODE AND B.PRESENTN_NO = AMT.PRESENTN_NO
WHERE A.COMPANY_CODE = #{COMPANY_CODE} AND A.ISSUE_TYPE = #{SEARCH_ISSUE_TYPE} AND A.DRWBAK_AMOUNT > 4999 AND A.STTEMNT_PC_KRW > 0
AND A.CHIT_FRMTRM_DATE BETWEEN REPLACE(#{SEARCH_FROM_DATE}, '-', '') AND REPLACE(#{SEARCH_TO_DATE}, '-', '')
AND B.ITEM_CODE = #{SEARCH_KEY_WORD}
AND B.ITEM_CODE LIKE #{SEARCH_KEY_WORD}|| '%'
AND B.ITEM_CODE LIKE '%'||#{SEARCH_KEY_WORD}|| '%'
AND B.ITEM_NM = #{SEARCH_KEY_WORD}
AND B.ITEM_NM LIKE #{SEARCH_KEY_WORD}|| '%'
AND B.ITEM_NM LIKE '%'||#{SEARCH_KEY_WORD}|| '%'
AND A.HS_CODE = #{HS_CODE}
AND A.REGIST_RCEPT_NO = #{REGIST_RCEPT_NO}
AND C.CUSTOMER_CODE = #{CUSTOMER_CODE}
AND A.PRESENTN_NO = #{PRESENTN_NO}
AND A.EXECUT_STATUS = #{EXECUT_STATUS}
GROUP BY A.PRESENTN_NO,ISSUE_TYPE,A.CSTMR_NM_1,A.RPRSNTV_NM_1,A.HS_CODE,AMT.STTEMNT_PC_KRW,A.BASS_UNIT,AMT.DRWBAK_AMOUNT,A.DRWBAK_AMOUNT ,A.EXECUT_AT,A.COMPANY_CODE,A.DIVISION_CODE,A.BASE_SOURCE_YYYYMM,A.CUSTOMER_CODE, A.SUBMIT_NO, A.EXECUT_STATUS, A.REGIST_RCEPT_NO
GROUP BY A.PRESENTN_NO,ISSUE_TYPE,A.CSTMR_NM_1,A.RPRSNTV_NM_1,A.HS_CODE,A.STTEMNT_PC_KRW,A.BASS_UNIT,A.DRWBAK_AMOUNT ,A.EXECUT_AT,A.COMPANY_CODE,A.DIVISION_CODE,A.BASE_SOURCE_YYYYMM,A.CUSTOMER_CODE, A.SUBMIT_NO, A.EXECUT_STATUS, A.REGIST_RCEPT_NO
ORDER BY A.PRESENTN_NO ASC

SELECT * FROM (SELECT A.DRWBAK_MONTH ,A.REGIST_RCEPT_NO ,TO_CHAR(A.DRWBAK_COMP_DATE, 'RRRRMMDD') AS DRWBAK_COMP_DATE ,A.XPORT_TYPE ,A.DRWBAK_AMOUNT ,A.LF_PRICE_TRGT ,A.TAX_RATE_TRGT ,CASE WHEN B.OVER_DRWBAK_PRESENTN_NO IS NULL THEN 'N' ELSE 'Y' END AS DOC_WRITE_YN ,CASE WHEN C.EXECUT_AT IS NULL THEN 'N' ELSE C.EXECUT_AT END AS SEND_REQ_YN ,TO_CHAR(A.DRWBAK_COMP_DATE + (365*4) + 364, 'RRRRMMDD') AS SELF_YYYYMMDD ,CASE WHEN C.RCEPT_DATE IS NOT NULL THEN TO_CHAR(TO_DATE(C.RCEPT_DATE, 'RRRRMMDD') + 15, 'RRRRMMDD') ELSE '' END OVER_TAX_DATE ,'ATTECH_FILE' AS ATTECH_FILE ,'ATTECH_KEY' AS ATTECH_KEY ,B.OVER_DRWBAK_PRESENTN_NO ,A.PRESENTN_NO ,NVL(C.EXECUT_STATUS, 'XX') AS EXECUT_STATUS ,C.EXECUT_AT ,C.SUBMIT_NO ,C.REGIST_RCEPT_NO AS OVER_REGIST_RCEPT_NO FROM DRWBAK_REQSTDOC_CMMN A LEFT OUTER JOIN OVER_DRWBAK_VOL_DECL_ITEM B ON A.COMPANY_CODE = B.COMPANY_CODE AND A.DIVISION_CODE = B.DIVISION_CODE AND A.PRESENTN_NO = B.PRE_PRESENTN_NO LEFT OUTER JOIN OVER_DRWBAK_VOL_DECL_HDR C ON B.COMPANY_CODE = C.COMPANY_CODE AND B.DIVISION_CODE = C.DIVISION_CODE AND B.OVER_DRWBAK_PRESENTN_NO = C.OVER_DRWBAK_PRESENTN_NO WHERE A.DRWBAK_COMP_DATE IS NOT NULL AND A.COMPANY_CODE = #{COMPANY_CODE} AND A.DRWBAK_MONTH BETWEEN REPLACE(#{DRWBAK_MONTH_FROM}, '-', '') AND REPLACE(#{DRWBAK_MONTH_TO}, '-', '')
AND SUBSTR(A.DRWBAK_REQ_DATE,1,8) BETWEEN #{SEARCH_COMP_FROM_DATE} AND #{SEARCH_COMP_TO_DATE}
AND A.REGIST_RCEPT_NO = #{REGIST_RCEPT_NO}
AND SUBSTR(A.DRWBAK_REQ_DATE,1,8) BETWEEN #{SEARCH_RECEIP_FROM_DATE} AND #{SEARCH_RECEIP_TO_DATE}
AND C.EXECUT_STATUS = #{EXECUT_STATUS}
) A WHERE 1 = 1
AND A.DOC_WRITE_YN = 'Y'
AND A.DOC_WRITE_YN = 'N'
AND A.SEND_REQ_YN = 'Y'
AND A.SEND_REQ_YN = 'N'

SELECT CC.PRESENTN_NO ,CC.REGIST_RCEPT_NO ,CC.CHIT_FRMTRM_DATE ,CC.ISSUE_TYPE ,CASE WHEN CC.ISSUE_TYPE = '02' THEN '기납증' WHEN CC.ISSUE_TYPE = '04' THEN '분증' ELSE '알수없는코드' END AS ISSUE_TYPE_NAME ,CC.CUSTOMER_CODE ,CC.CSTMR_NM_1 ,DECODE(MUWM.MCRTF_PRESENTN_NO,NULL,'N','Y') AS REGIST_YN ,DECODE(MUWM.RCEPT_DATE,NULL,'N','Y') AS RCEPT_YN ,DECODE(MUWM.NTICE_DATE,NULL,'N','Y') AS NTICE_YN ,MUWM.RCEPT_DATE ,MUWM.NTICE_DATE ,CC.COMPANY_CODE ,CC.DIVISION_CODE ,MUWM.MCRTF_PRESENTN_NO ,MUWM.MCRTF_REGIST_RCEPT_NO FROM CTRM_CMMN CC LEFT OUTER JOIN MCRTF_UPDT_WTHDRW_MST MUWM ON MUWM.COMPANY_CODE = CC.COMPANY_CODE AND MUWM.DIVISION_CODE = CC.DIVISION_CODE AND MUWM.PRESENTN_NO = CC.PRESENTN_NO
WHERE CC.COMPANY_CODE = #{COMPANY_CODE} AND SUBSTR(CC.CHIT_FRMTRM_DATE,1,6) BETWEEN REPLACE(#{CHIT_FRMTRM_MONTH_FROM}, '-', '') AND REPLACE(#{CHIT_FRMTRM_MONTH_TO}, '-', '')
AND MUWM.RCEPT_DATE BETWEEN #{SEARCH_RCEPT_FROM_DATE} AND #{SEARCH_RCEPT_TO_DATE}
AND MUWM.NTICE_DATE BETWEEN #{SEARCH_NTICE_FROM_DATE} AND #{SEARCH_NTICE_TO_DATE}
AND CC.ISSUE_TYPE = #{ISSUE_TYPE}
AND CC.REGIST_RCEPT_NO = #{SEARCH_KEY_WORD}
AND CC.REGIST_RCEPT_NO LIKE #{SEARCH_KEY_WORD}|| '%'
AND CC.REGIST_RCEPT_NO LIKE '%'||#{SEARCH_KEY_WORD}|| '%'
AND CC.CUSTOMER_CODE = #{SEARCH_KEY_WORD}
AND CC.CUSTOMER_CODE LIKE #{SEARCH_KEY_WORD}|| '%'
