   AND A.PRESENTN_NO = #{KEY_PRESENTN_NO}

mapper.insert:
	    
            SELECT NVL(MAX(A.SEQ), 0) +1 AS PRE_THNG_SEQ_NUMBER
              FROM CTRM_TRGET_THNG A
             WHERE A.PRESENTN_NO = #{KEY_PRESENTN_NO}
               AND A.COMPANY_CODE = #{COMPANY_CODE}
               AND A.DIVISION_CODE = #{DIVISION_CODE}
         
            INSERT INTO CTRM_TRGET_THNG
                (COMPANY_CODE,DIVISION_CODE,PRESENTN_NO,SEQ,ITEM_CODE,ITEM_NM,ACCMLT_ORDER_QY,BASS_UNIT,STTEMNT_PC_KRW,KRW_CRNCY,CSTMS
					,INTTAX,ECX_AMOUNT,AGSPT,TRANTAX,LQTX_AMOUNT,DRWBAK_AMOUNT,ACPLC_CRNCY,BASIS_DOC_NO,SUPT_DOC_SE,CSTMR_ITEM,SUPT_DOC_ITEM_SEQ,CHIT_FRMTRM_DATE)
            VALUES
                (#{COMPANY_CODE},#{DIVISION_CODE},#{PRESENTN_NO},${PRE_THNG_SEQ_NUMBER},#{ITEM_CODE},#{ITEM_NM},#{TGT_ACCMLT_ORDERQTY},#{BASS_UNIT},#{STTEMNT_PC_KRW},#{KRW_CRNCY},#{CSTMS}
                	,#{INTTAX},#{ECX_AMOUNT},#{AGSPT},#{TRANTAX},#{LQTX_AMOUNT},#{DRWBAK_AMOUNT},#{ACPLC_CRNCY},#{BASIS_DOC_NO},#{SUPT_DOC_SE},#{CSTMR_ITEM},#{SUPT_DOC_ITEM_SEQ},#{CHIT_FRMTRM_DATE})

mapper.select:
		SELECT A.COMPANY_CODE, A.DIVISION_CODE, A.XPORT_STTEMNT_NO, TO_NUMBER(A.ABLE_CTRM_QTY) AS REMNDR_QY
               , A.ITEM_CODE AS PRODUCT_CODE
               , (CASE WHEN A.ABLE_CTRM_QTY - ${EXP_ACCMLT_ORDERQTY}  >=  0 THEN ${EXP_ACCMLT_ORDERQTY} ELSE A.ABLE_CTRM_QTY END) AS USGQTY
               , (CASE WHEN A.ABLE_CTRM_QTY - ${EXP_ACCMLT_ORDERQTY}  >=  0 THEN A.ABLE_CTRM_QTY - ${EXP_ACCMLT_ORDERQTY} ELSE 0 END) AS UPDATE_REMNDR_QY
               , (CASE WHEN A.ABLE_CTRM_QTY - ${EXP_ACCMLT_ORDERQTY}  >=  0 THEN 0 ELSE ABS(${EXP_ACCMLT_ORDERQTY} - A.ABLE_CTRM_QTY) END) AS NEXT_MINUS_VALUE
               ,A.LNE_NO
               ,A.POUCH_NO
          FROM EXPORT_CERT_MST A
         WHERE A.COMPANY_CODE != #{COMPANY_CODE}
           AND A.DIVISION_CODE != #{DIVISION_CODE}
           AND A.ITEM_CODE = #{ITEM_CODE}
           AND A.DSPTH_DATE BETWEEN TO_CHAR(TO_DATE(#{CHIT_FRMTRM_DATE}, 'YYYYMMDD')+1, 'YYYYMMDD') AND TO_CHAR(ADD_MONTHS(TO_DATE(#{CHIT_FRMTRM_DATE}, 'YYYYMMDD'), +23)-1 , 'YYYYMMDD')
           AND A.ABLE_CTRM_QTY > 0
           AND A.XPORT_STTEMNT_NO =
               (SELECT A.XPORT_STTEMNT_NO
                  FROM EXPORT_CERT_MST A
                 WHERE A.DSPTH_DATE =
                       (SELECT MIN(A.DSPTH_DATE)
                          FROM EXPORT_CERT_MST A
                         WHERE A.COMPANY_CODE != #{COMPANY_CODE}
                           AND A.DIVISION_CODE != #{DIVISION_CODE}
                           AND A.ITEM_CODE = #{ITEM_CODE}
                           AND A.DSPTH_DATE BETWEEN TO_CHAR(TO_DATE(#{CHIT_FRMTRM_DATE}, 'YYYYMMDD')+1, 'YYYYMMDD') AND TO_CHAR(ADD_MONTHS(TO_DATE(#{CHIT_FRMTRM_DATE}, 'YYYYMMDD'), +23)-1 , 'YYYYMMDD')
                           AND A.ABLE_CTRM_QTY > 0)
                   AND A.COMPANY_CODE  != #{COMPANY_CODE}
                   AND A.DIVISION_CODE !=  #{DIVISION_CODE}
                   AND A.ITEM_CODE = #{ITEM_CODE}
                   AND A.DSPTH_DATE BETWEEN TO_CHAR(TO_DATE(#{CHIT_FRMTRM_DATE}, 'YYYYMMDD')+1, 'YYYYMMDD') AND TO_CHAR(ADD_MONTHS(TO_DATE(#{CHIT_FRMTRM_DATE}, 'YYYYMMDD'), +23)-1 , 'YYYYMMDD')
                   AND A.ABLE_CTRM_QTY > 0
                   AND ROWNUM = 1)

mapper.update:

      UPDATE EXPORT_CERT_MST A
         SET A.ABLE_CTRM_QTY =  #{UPDATE_REMNDR_QY}
       WHERE A.COMPANY_CODE = #{COMPANY_CODE}
         AND A.DIVISION_CODE = #{DIVISION_CODE}
         AND A.XPORT_STTEMNT_NO = #{IMPDEC_NO}
         AND A.ITEM_CODE = #{ITEM_CODE}
         AND A.LNE_NO = #{LNE_NO}
         AND A.POUCH_NO = #{POUCH_NO}

mapper.select:
SELECT H.COMPANY_CODE , H.DIVISION_CODE , H.PRESENTN_NO , H.STTEMNT_DOC_STLE , H.JUDGE_REQ_DOC_TYPE , C.CODE_NM AS JUDGE_REQ_DOC_NAME , H.REGIST_RCEPT_NO , H.REGIST_RCEPT_DATE , H.JUDGE_REQ_DOC_NO , H.JUDGE_REQ_DOC_SEQ , H.REL_REGIST_RCEPT_NO , H.EXECUT_STATUS , H.SUBMIT_NO FROM DOC_QUICK_REFERENCE_HDR H INNER JOIN DOC_QUICK_REFERENCE_ITEM I ON H.COMPANY_CODE = I.COMPANY_CODE AND H.DIVISION_CODE = I.DIVISION_CODE AND H.PRESENTN_NO = I.PRESENTN_NO INNER JOIN COM_CD C ON H.JUDGE_REQ_DOC_TYPE = C.CODE_CD AND C.CATEGORY_CD = 'DOCTY' WHERE H.COMPANY_CODE = #{COMPANY_CODE} AND TO_CHAR(H.CREATE_DATE, 'YYYYMMDD') BETWEEN #{SEARCH_REGIST_RCEPT_FROM_DATE} AND #{SEARCH_REGIST_RCEPT_TO_DATE}
AND I.PRODUCT_CODE LIKE #{SEARCH_PRODUCT_CODE} || '%'
AND I.REF_NO LIKE #{SEARCH_REF_NO} || '%'
AND H.JUDGE_REQ_DOC_TYPE LIKE #{SEARCH_JUDGE_REQ_DOC_TYPE} || '%'
AND H.EXECUT_STATUS = #{EXECUT_STATUS}
AND H.REL_REGIST_RCEPT_NO = #{SEARCH_REL_REGIST_RCEPT_NO}
GROUP BY H.COMPANY_CODE , H.DIVISION_CODE , H.PRESENTN_NO , H.STTEMNT_DOC_STLE , H.JUDGE_REQ_DOC_TYPE , C.CODE_NM , H.REGIST_RCEPT_NO , H.REGIST_RCEPT_DATE , H.JUDGE_REQ_DOC_NO , H.JUDGE_REQ_DOC_SEQ , H.REL_REGIST_RCEPT_NO , H.EXECUT_STATUS , H.SUBMIT_NO

mapper.delete:
DELETE
  FROM DOC_QUICK_REFERENCE_ITEM
 WHERE COMPANY_CODE = #{COMPANY_CODE}
   AND PRESENTN_NO = #{PRESENTN_NO}

mapper.update:
           INSERT INTO DOC_QUICK_REFERENCE_ITEM (
		                COMPANY_CODE
		               ,DIVISION_CODE
		               ,PRESENTN_NO
		               ,SEQ
		               ,PRODUCT_CODE
		               ,REF_NO
		               ,REF_LNE_NO
		               ,REF_POUCH_NO
		               ,CREATE_DATE
		               ,CREATE_BY
		               ,UPDATE_DATE
		               ,UPDATE_BY
		              )
		       VALUES (
		                #{COMPANY_CODE}
		               ,#{DIVISION_CODE}
		               ,#{PRESENTN_NO}
		               ,#{SEQ}               
		               ,#{PRODUCT_CODE}
		               ,#{REF_NO}
		               ,#{REF_LNE_NO}
		               ,#{REF_POUCH_NO}
		               ,SYSDATE
		               ,''
		               ,SYSDATE
		               ,''
		       )

mapper.select:
    
			SELECT 'notification' AS KEY, COUNT(*) AS CNT
			       FROM AN_UNIPASS_R54 -- 접수통보
			       WHERE COMPANY_CODE = #{COMPANY_CODE}
					AND DIVISION_CODE = #{DIVISION_CODE}
					AND SUBMIT_NO = #{SUBMIT_NO}
			       
			        AND REGIST_RCEPT_NO = #{REGIST_RCEPT_NO}
			       
			UNION ALL 
			SELECT 'error' AS KEY, COUNT(*) AS CNT
			       FROM AN_UNIPASS_R20 -- 오류통보
			       WHERE COMPANY_CODE = #{COMPANY_CODE}
					AND DIVISION_CODE = #{DIVISION_CODE}
					AND SUBMIT_NO = #{SUBMIT_NO}
			
			UNION ALL 
			SELECT 'complement' AS KEY, COUNT(*) AS CNT
			       FROM AN_UNIPASS_R58 -- 보완통보
			       WHERE COMPANY_CODE = #{COMPANY_CODE}
					AND DIVISION_CODE = #{DIVISION_CODE}
					AND REGIST_RCEPT_NO = #{REGIST_RCEPT_NO}
			
			
			UNION ALL 
			SELECT 'request' AS KEY, COUNT(*) AS CNT
	             FROM  AN_UNIPASS_R57 -- 자료제출요구통보
	             WHERE COMPANY_CODE = #{COMPANY_CODE}
					AND DIVISION_CODE = #{DIVISION_CODE}
					AND MAIN_REGIST_RCEPT_NO = #{REGIST_RCEPT_NO} -- 접수 번호
			
			UNION ALL 
				 SELECT 'complete' AS KEY, COUNT(*) AS CNT
	             FROM  AN_UNIPASS_5DF -- 완료통보
	             WHERE COMPANY_CODE = #{COMPANY_CODE}
					AND DIVISION_CODE = #{DIVISION_CODE}
					AND SUBMIT_NO = #{SUBMIT_NO}
	             
	             AND REGIST_RCEPT_NO = #{REGIST_RCEPT_NO}
	             
		  
			UNION ALL 
			SELECT 'payment' AS KEY, COUNT(*) AS CNT
			       FROM AN_UNIPASS_381 -- 지급통보
			       WHERE COMPANY_CODE = #{COMPANY_CODE}
					AND DIVISION_CODE = #{DIVISION_CODE}
					AND PAY_ORDER_NO  = #{REGIST_RCEPT_NO} -- 접수 번호

    
			SELECT CASE A.PL_TYPE WHEN '1' THEN 'PL' WHEN '2' THEN '서류제출' ELSE A.PL_TYPE END AS PL_TYPE
				, A.STTEMNT_DOC_STLE, A.CSMHSE_PRSN, A.SUBMIT_NO 
		        , NVL(B.CODE_NM, SUBSTR(A.CSMHSE_CODE, 1, 3)) AS CATEGORY_NM
		        , TO_CHAR(TO_DATE(A.REGIST_RCEP_DATE, 'YYYYMMDDHH24MISS'), 'YYYY-MM-DD HH24:MI:SS') AS REGIST_RCEP_DATE --수신일시
		        , TO_CHAR(TO_DATE(A.COMPLETE_DATE, 'YYYYMMDDHH24MISS'), 'YYYY-MM-DD HH24:MI:SS') AS COMPLETE_DATE --접수일시
			FROM AN_UNIPASS_R54 A
			      LEFT JOIN COM_CD B
			           			ON B.CATEGORY_CD = 'CT'
			           			AND SUBSTR(A.CSMHSE_CODE, 1, 3) = B.CODE_CD 
			WHERE A.COMPANY_CODE = #{COMPANY_CODE}
			AND A.DIVISION_CODE = #{DIVISION_CODE}
			AND A.SUBMIT_NO = #{SUBMIT_NO}
			
			AND A.REGIST_RCEPT_NO = #{REGIST_RCEPT_NO}

    
			
			SELECT A.SUBMIT_STTEMNT_DOC_STLE
				, A.ERROR_MESSAGE
				, TO_CHAR(A.CREATE_DATE, 'YYYY-MM-DD HH24:MI:SS') AS CREATE_DATE
			FROM AN_UNIPASS_R20_ITEM A 
			WHERE A.COMPANY_CODE = #{COMPANY_CODE}
			AND A.DIVISION_CODE = #{DIVISION_CODE}
			AND A.SUBMIT_NO = #{SUBMIT_NO}
			ORDER BY A.ERROR_SEQ

    
		SELECT A.STTEMNT_DOC_STLE -- 문서형태구분
		       , A.COMPLETE_DATE -- 통보일시
		       , A.CSMHSE_PRSN -- 처리담당자
		       , A.INSPECTIONENDDATE -- 심사완료일자
		       , NVL(B.CODE_NM, SUBSTR(A.CSMHSE_CODE, 1, 3)) AS CSMHSE_NAME
		FROM  AN_UNIPASS_5DF A
		LEFT JOIN COM_CD B
			ON B.CATEGORY_CD = 'CT'
			AND SUBSTR(A.CSMHSE_CODE, 1, 3) = B.CODE_CD			
		WHERE A.COMPANY_CODE = #{COMPANY_CODE}
			AND A.DIVISION_CODE = #{DIVISION_CODE}
			AND A.SUBMIT_NO = #{SUBMIT_NO}
			
	        AND A.REGIST_RCEPT_NO = #{REGIST_RCEPT_NO}

mapper.delete:
DELETE FROM ADAMT_PAMT_DOC_ITEM A
 WHERE A.COMPANY_CODE = #{COMPANY_CODE}
   AND A.DIVISION_CODE = #{DIVISION_CODE}
   AND A.PRESENTN_NO = #{PRESENTN_NO}

mapper.insert:

	SELECT LPAD(NVL(MAX(Z.SEQ), 0)+1, 4, '0') AS SEQ 
	  FROM ADAMT_PAMT_DOC_ITEM Z
	 WHERE Z.COMPANY_CODE = #{COMPANY_CODE}
	   AND Z.DIVISION_CODE = #{DIVISION_CODE}
	   AND Z.PRESENTN_NO = #{PRESENTN_NO}

INSERT INTO ADAMT_PAMT_DOC_ITEM
	(COMPANY_CODE,DIVISION_CODE,PRESENTN_NO,SEQ,PRE_REGIST_RCEPT_NO,IDV_PAMT_NO,IDV_PAMT_DATE,TAX_TYPE,
	PRE_DRWBAK_AMOUNT,ADAMT,OVER_REGIST_RCEPT_NO, PROPER_DRWBAK_AMOUNT,PAMT_REQ_ADAMT,CREATE_DATE,PROPER_REGIST_RCEPT_NO)
VALUES  (#{COMPANY_CODE} ,#{DIVISION_CODE},#{PRESENTN_NO},#{KEY_SEQ},#{PRE_REGIST_RCEPT_NO},#{IDV_PAMT_NO},#{IDV_PAMT_DATE},#{TAX_TYPE}
    ,#{PRE_DRWBAK_AMOUNT},#{ADAMT},#{OVER_REGIST_RCEPT_NO},#{PROPER_DRWBAK_AMOUNT},#{PAMT_REQ_ADAMT},SYSDATE,#{PROPER_REGIST_RCEPT_NO})
